import torch
import numpy as np
import re
from pathlib import Path
from transformers import AutoTokenizer, AutoModelForTokenClassification

# 1. Initialize local model objects
local_dir = Path(__file__).parent / "best_rabbinic_ner_model"
model_path = str(local_dir.resolve())

label_list = ["O", "B-AUTHORITY_OR_SOURCE", "I-AUTHORITY_OR_SOURCE", "B-BOOK_LOCATION", "I-BOOK_LOCATION", "B-SOURCE_PATH", "I-SOURCE_PATH"]
num_valid_classes = len(label_list)

print(f"[SYSTEM] Loading tokenizer and model...")
tokenizer = AutoTokenizer.from_pretrained(model_path, local_files_only=True)
model = AutoModelForTokenClassification.from_pretrained(model_path, local_files_only=True).cpu()
model.eval()

def split_into_sentences(text: str):
    """Splits long transcripts into safe sentence chunks."""
    sentences = re.split(r'([.!?]+)\s*', text)
    
    # These MUST be defined here so the loops below can see them
    entities_found = False
    current_entity_tokens = []
    current_entity_label = None

    def flush_entity_block():
        nonlocal current_entity_tokens, current_entity_label, entities_found
        if current_entity_tokens and current_entity_label:
            full_word = " ".join(current_entity_tokens)
            print(f"  [{current_entity_label}] -> '{full_word}'")
            entities_found = True
        current_entity_tokens = []
        current_entity_label = None
        
    for sentence in sentences:
        words = sentence.split()
        if not words:
            continue
            
        inputs = tokenizer(words, is_split_into_words=True, return_tensors="pt")
        
        # Guard against single massive sentences overflowing 512 bounds
        if inputs["input_ids"].shape[1] > 512:
            inputs = tokenizer(words, is_split_into_words=True, return_tensors="pt", truncation=True, max_length=512)
            
        with torch.no_grad():
            outputs = model(**inputs)
            clean_logits = outputs.logits[:, :, :num_valid_classes]
            predictions = torch.argmax(clean_logits, dim=2).squeeze(0).numpy()
            
        word_ids = inputs.word_ids()
        previous_word_idx = None
        
        for idx, word_idx in enumerate(word_ids):
            if word_idx is None or word_idx == previous_word_idx:
                continue
                
            pred_id = predictions[idx]
            label_string = label_list[pred_id]
            raw_word = words[word_idx]
            
            if label_string.startswith("B-"):
                flush_entity_block()
                current_entity_label = label_string.split("-")[1]
                current_entity_tokens = [raw_word]
            elif label_string.startswith("I-"):
                expected_label = label_string.split("-")[1]
                if current_entity_label == expected_label:
                    current_entity_tokens.append(raw_word)
                else:
                    flush_entity_block()
            else:
                flush_entity_block()
                
            previous_word_idx = word_idx
            
        flush_entity_block() # Flush at end of sentence
        
    if not entities_found:
        print("  (No entities detected in this transcript)")

